return {
  backgroundColor: 'transparent',
  grid: { left: 110, right: 30, top: 10, bottom: 30, containLabel: false },
  tooltip: {
    trigger: 'item',
    backgroundColor: 'rgba(36, 9, 53, 0.95)',
    borderColor: '#5000BF',
    borderWidth: 1,
    textStyle: { color: '#E6E6E6', fontFamily: 'Inter' },
