  backgroundColor: 'transparent',
  grid: { left: 60, right: 20, top: 20, bottom: 40, containLabel: true },
  tooltip: {
    trigger: 'axis',
    backgroundColor: 'rgba(36, 9, 53, 0.95)',
    borderColor: '#5000BF',
    borderWidth: 1,
    textStyle: { color: '#E6E6E6', fontFamily: 'Inter' },
    formatter: (params) => {
      const p = params[0];
      return '<b style="color:#CC0AAC">Era ' + p.name + '</b><br/>Reward: <b>' + Number(p.value).toLocaleString('en-US') + '</b>';
    },
    axisPointer: { type: 'shadow', shadowStyle: { color: 'rgba(204, 10, 172, 0.1)' } },
  },
  xAxis: {
    type: 'category',
    data: eras.map(e => String(e)),
    axisLine:  { lineStyle: { color: '#3A1857' } },
    axisTick:  { show: false },
    axisLabel: { color: '#A090B5', fontFamily: 'JetBrains Mono', fontSize: 9 },
  },
  yAxis: {
    type: 'value',
    axisLine:  { show: false },
    axisTick:  { show: false },
    axisLabel: { color: '#A090B5', fontFamily: 'JetBrains Mono', fontSize: 9 },
    splitLine: { lineStyle: { color: 'rgba(58, 24, 87, 0.4)', type: 'dashed' } },
  },
  series: [{
    type: 'bar',
    data: Array.from(rewards).map(v => Number(v)),
    itemStyle: {
      color: {
        type: 'linear', x: 0, y: 0, x2: 0, y2: 1,
        colorStops: [
          { offset: 0, color: '#CC0AAC' },
          { offset: 1, color: '#5000BF' },
        ],
      },
      borderRadius: [3, 3, 0, 0],
    },
    emphasis: {
      itemStyle: { shadowBlur: 10, shadowColor: 'rgba(204, 10, 172, 0.7)' },
    },
    barWidth: '60%',
  }],
};

const frame = context.panel.data.series[0];
if (!frame) return { title: { text: 'No data', left: 'center', top: 'middle', textStyle: { color: '#6F4D80' } } };

const eraField    = frame.fields.find(f => f.name === 'era');
const inflowsF    = frame.fields.find(f => f.name === 'inflows');
const outflowsF   = frame.fields.find(f => f.name === 'outflows');
const netChangeF  = frame.fields.find(f => f.name === 'net_change');
if (!eraField) return {};

const eras     = eraField.values.buffer || eraField.values;
const inflows  = inflowsF  ? (inflowsF.values.buffer  || inflowsF.values)  : [];
const outflows = outflowsF ? (outflowsF.values.buffer || outflowsF.values) : [];
const netCh    = netChangeF? (netChangeF.values.buffer|| netChangeF.values): [];

return {
  backgroundColor: 'transparent',
  legend: {
    data: ['Inflows', 'Outflows', 'Net change'],
    top: 5,
    textStyle: { color: '#A090B5', fontFamily: 'Inter', fontSize: 10 },
    itemWidth: 10, itemHeight: 10,
  },
  grid: { left: 60, right: 20, top: 35, bottom: 40, containLabel: true },
  tooltip: {
    trigger: 'axis',
    backgroundColor: 'rgba(36, 9, 53, 0.95)',
    borderColor: '#5000BF',
    borderWidth: 1,
    textStyle: { color: '#E6E6E6', fontFamily: 'Inter' },
    axisPointer: { type: 'shadow', shadowStyle: { color: 'rgba(204, 10, 172, 0.1)' } },
  },
  xAxis: {
    type: 'category',
    data: Array.from(eras).map(e => String(e)),
    axisLine:  { lineStyle: { color: '#3A1857' } },
    axisTick:  { show: false },
    axisLabel: { color: '#A090B5', fontFamily: 'JetBrains Mono', fontSize: 9 },
  },
  yAxis: {
    type: 'value',
    axisLine:  { show: false },
    axisTick:  { show: false },
    axisLabel: { color: '#A090B5', fontFamily: 'JetBrains Mono', fontSize: 9 },
    splitLine: { lineStyle: { color: 'rgba(58, 24, 87, 0.4)', type: 'dashed' } },
  },
  series: [
    {
      name: 'Inflows',
      type: 'bar',
      data: Array.from(inflows).map(v => Number(v)),
      itemStyle: { color: '#22c55e', borderRadius: [2, 2, 0, 0] },
      barGap: '10%', barWidth: '28%',
    },
    {
      name: 'Outflows',
      type: 'bar',
      data: Array.from(outflows).map(v => -Math.abs(Number(v))),
      itemStyle: { color: '#ef4444', borderRadius: [2, 2, 0, 0] },
      barWidth: '28%',
    },
    {
      name: 'Net change',
      type: 'line',
      data: Array.from(netCh).map(v => Number(v)),
      smooth: true,
      lineStyle: { color: '#CC0AAC', width: 2 },
      itemStyle: { color: '#CC0AAC' },
      symbol: 'circle',
      symbolSize: 5,
    },
  ],
};
